insert into public.piece_templates
  (category, name, content_type, suggested_format, objective, audience, experience, spec_text, words_guide)
values
  ('conectar', 'Humor / meme', 'Meme / humor', 'post', 'Generar cercanía e interacción (comentarios, compartidos) mostrando el lado humano de la marca.', 'Comunidad actual y personas que se identifican con el día a día de la marca.', 'La persona se ríe porque se reconoce en la situación y siente que la marca la entiende.', 'Formato: imagen o video corto (≤15 s). Una sola idea graciosa, fácil de leer en 2 segundos. Respetar tono de la marca; evitar humor que ridiculice a personas.', '{"hook": "¿Qué situación graciosa reconoce tu audiencia al instante?", "caption": "¿Cómo invitas a etiquetar a alguien que vive lo mismo?", "cta": "¿Qué quieres que hagan: comentar, compartir, etiquetar?"}'::jsonb),
  ('conectar', 'Momento emotivo', 'Video / foto emotiva', 'reel', 'Crear vínculo emocional con la comunidad a partir de un momento real y significativo.', 'Comunidad actual, familias y personas cercanas a la marca.', 'La persona se emociona con un momento auténtico y siente orgullo o pertenencia.', 'Formato: reel 20–45 s o foto con texto. Música acorde (sin derechos restringidos). Mostrar personas reales con autorización de imagen cuando aplique.', '{"hook": "¿Cuál es el instante que hace sentir algo en los primeros 2 segundos?", "final_line": "¿Con qué frase cierras para que se quede la emoción?", "caption": "¿Qué historia breve hay detrás del momento?"}'::jsonb),
  ('conectar', 'Situación cotidiana (POV)', 'Reel POV / «cuando…»', 'reel', 'Aumentar alcance e identificación con contenido que retrata situaciones cotidianas de la audiencia.', 'Personas que viven la situación representada y su círculo cercano.', 'La persona piensa «así me pasa» y lo comparte con alguien.', 'Formato: reel 10–30 s, texto en pantalla «POV:» o «Cuando…». Actuación sencilla, sin producción compleja.', '{"on_screen": "¿Cuál es el texto «POV / Cuando…» que lo resume?", "hook": "¿Qué pasa en el primer segundo?", "caption": "¿Qué pregunta invita a contar su propia versión?"}'::jsonb),
  ('conectar', 'Detrás de cámaras', 'Detrás de cámaras', 'story', 'Mostrar el proceso y a las personas detrás del contenido o del servicio para generar confianza.', 'Comunidad actual y personas interesadas en cómo trabaja la marca.', 'La persona descubre algo que normalmente no ve y siente más cercanía.', 'Formato: stories o reel corto con clips del proceso. Natural, sin guion rígido.', '{"hook": "¿Qué parte del proceso sorprende más?", "on_screen": "¿Qué texto breve explica lo que se ve?", "cta": "¿Invitas a preguntar algo sobre el proceso?"}'::jsonb),
  ('conectar', 'Testimonio / historia', 'Testimonio', 'reel', 'Contar una historia real de una persona de la comunidad que refleje los valores de la marca.', 'Comunidad actual y personas que se parecen a la protagonista de la historia.', 'La persona conoce a alguien real, se identifica con su historia y confía más en la marca.', 'Formato: reel 30–60 s o carrusel con cita. Autorización de la persona y de imagen. Subtítulos.', '{"hook": "¿Qué frase de la persona engancha de inmediato?", "final_line": "¿Cuál es el aprendizaje o cierre de la historia?", "caption": "¿Qué contexto mínimo necesita quien no la conoce?"}'::jsonb),
  ('educativo', 'Carrusel de tips', 'Carrusel', 'carousel', 'Aportar valor práctico y posicionar a la marca como referente; generar guardados y compartidos.', 'Personas interesadas en el tema que buscan consejos aplicables.', 'La persona reconoce un problema, recorre los tips rápido y termina con algo aplicable hoy.', 'Formato: carrusel 5–8 slides (portada + tips + cierre/CTA), 1080×1350. Título corto y 1–2 líneas por slide. Identidad visual de la marca.', '{"hook": "¿Qué problema o error común plantea la portada?", "final_line": "¿Qué idea quieres que se lleve?", "cta": "¿Guardar, compartir o seguir?"}'::jsonb),
  ('educativo', 'Explicación de un concepto', 'Carrusel / reel explicativo', 'carousel', 'Explicar de forma simple un concepto relevante para la audiencia.', 'Personas que se inician en el tema.', 'La persona entiende algo que le parecía complejo y siente que aprendió en poco tiempo.', 'Formato: carrusel 5–7 slides o reel 30–60 s. Definición, ejemplo y aplicación. Lenguaje sencillo.', '{"hook": "¿Qué pregunta responde el concepto?", "on_screen": "¿Cuál es la definición en una línea?", "cta": "¿Qué siguiente paso propones?"}'::jsonb),
  ('educativo', 'Paso a paso / tutorial', 'Tutorial', 'reel', 'Enseñar a hacer algo concreto en pocos pasos.', 'Personas que quieren resolver una tarea específica.', 'La persona sigue los pasos y logra el resultado.', 'Formato: reel 30–60 s o carrusel con pasos numerados. Mostrar el resultado al inicio o al final.', '{"hook": "¿Qué resultado prometes al inicio?", "on_screen": "¿Cuáles son los pasos en una línea cada uno?", "cta": "¿Invitas a guardar para hacerlo después?"}'::jsonb),
  ('educativo', 'Mito vs. realidad', 'Carrusel mito/realidad', 'carousel', 'Corregir creencias erróneas frecuentes y aportar claridad.', 'Personas interesadas en el tema expuestas a información confusa.', 'La persona descubre que algo que creía no es cierto y confía en la marca como fuente.', 'Formato: carrusel con pares mito/realidad. Cada «realidad» con fuente verificable (registrar como claim).', '{"hook": "¿Qué mito llama más la atención?", "final_line": "¿Cuál es la conclusión?", "caption": "¿Qué fuente respalda las realidades?"}'::jsonb),
  ('educativo', 'Herramienta o recurso recomendado', 'Recomendación', 'carousel', 'Recomendar una herramienta o recurso útil y explicar cómo aprovecharlo.', 'Personas que buscan herramientas para mejorar su trabajo o aprendizaje.', 'La persona descubre un recurso nuevo y sabe exactamente para qué usarlo.', 'Formato: carrusel o reel corto mostrando el recurso en uso. Indicar si es gratuito o de pago.', '{"hook": "¿Qué problema resuelve el recurso?", "on_screen": "¿Cuál es el uso principal en una línea?", "cta": "¿Guardar o comentar si lo conocían?"}'::jsonb),
  ('cobertura', 'Previa / anuncio del evento', 'Anuncio de evento', 'post', 'Generar expectativa y asistencia/atención antes del evento.', 'Comunidad interesada en el evento y posibles asistentes.', 'La persona sabe qué, cuándo y dónde, y siente ganas de estar.', 'Formato: post o reel corto con fecha, hora y lugar claros. Confirmar datos con la organización del evento.', '{"hook": "¿Qué hace especial a este evento?", "on_screen": "¿Fecha, hora y lugar?", "cta": "¿Registrarse, asistir, activar recordatorio?"}'::jsonb),
  ('cobertura', 'Durante (en vivo / stories)', 'Stories en vivo', 'story', 'Transmitir el ambiente del evento en tiempo real.', 'Comunidad que sigue el evento a distancia y asistentes.', 'La persona siente que está ahí aunque no haya asistido.', 'Formato: secuencia de stories con momentos clave. Etiquetar cuentas relevantes. Cuidar autorizaciones de imagen.', '{"on_screen": "¿Qué texto breve ubica cada momento?", "cta": "¿Encuestas o preguntas para interactuar?"}'::jsonb),
  ('cobertura', 'Resumen post-evento', 'Resumen de evento', 'reel', 'Mostrar los mejores momentos y el impacto del evento.', 'Asistentes, comunidad y personas que no pudieron asistir.', 'La persona revive el evento o se queda con ganas de ir al siguiente.', 'Formato: reel 30–60 s o carrusel de fotos. Mejores tomas, cifras o frases clave si están verificadas.', '{"hook": "¿Cuál es la mejor toma para abrir?", "final_line": "¿Cómo cierras: agradecimiento, cifra, próximo evento?", "caption": "¿Qué datos del evento incluyes (verificados)?"}'::jsonb),
  ('cobertura', 'Momento destacado', 'Momento destacado', 'reel', 'Aislar un instante memorable del evento para maximizar alcance.', 'Comunidad amplia, no solo asistentes.', 'La persona ve un momento potente y entiende por qué importó el evento.', 'Formato: clip 10–20 s o foto única. Contexto mínimo en texto.', '{"hook": "¿Qué momento es irresistible?", "caption": "¿Qué contexto necesita quien no estuvo?"}'::jsonb),
  ('institucional', 'Comunicado', 'Comunicado', 'post', 'Informar de forma clara y oficial un tema relevante.', 'Comunidad de la institución y públicos interesados.', 'La persona entiende el mensaje sin ambigüedad y sabe si debe hacer algo.', 'Formato: post con texto claro o imagen con titular. Validar redacción con la persona responsable antes de publicar.', '{"on_screen": "¿Cuál es el titular del comunicado?", "caption": "¿Qué información completa y oficial incluye?", "cta": "¿Hay acción requerida o enlace?"}'::jsonb),
  ('institucional', 'Convocatoria / fechas', 'Convocatoria', 'post', 'Difundir una convocatoria o fechas importantes con datos exactos.', 'Personas a quienes va dirigida la convocatoria.', 'La persona sabe si le aplica, qué hacer y hasta cuándo.', 'Formato: post o carrusel con requisitos, fechas y enlace. Fechas verificadas con la fuente oficial (registrar como claim).', '{"hook": "¿A quién va dirigida y qué gana?", "on_screen": "¿Fechas clave?", "cta": "¿Dónde se registra o informa?"}'::jsonb),
  ('institucional', 'Logro o reconocimiento', 'Logro', 'post', 'Reconocer un logro y reforzar el orgullo de pertenencia.', 'Comunidad de la institución, familias y público general.', 'La persona siente orgullo y reconoce a quienes lo lograron.', 'Formato: post o carrusel con foto de las personas. Nombres y datos verificados; autorización de imagen.', '{"hook": "¿Cuál es el logro en una frase?", "caption": "¿Quiénes participaron y qué significó?"}'::jsonb),
  ('institucional', 'Efeméride', 'Efeméride', 'post', 'Conmemorar una fecha relevante de forma coherente con los valores de la marca.', 'Comunidad de la marca.', 'La persona recuerda la fecha y ve una conexión auténtica con la marca.', 'Formato: post sencillo. Evitar efemérides sin relación con la marca.', '{"hook": "¿Qué conexión real tiene la fecha con la marca?", "caption": "¿Qué mensaje breve y no genérico dejas?"}'::jsonb),
  ('promocional', 'Oferta o servicio', 'Oferta / servicio', 'carousel', 'Dar a conocer un servicio u oferta y generar contactos interesados.', 'Clientes potenciales con la necesidad que resuelve el servicio.', 'La persona entiende qué ofrece la marca, para quién es y cómo pedirlo.', 'Formato: carrusel o reel: problema → solución → beneficios → cómo contratar. Precios y condiciones solo si están confirmados (claim).', '{"hook": "¿Qué problema del cliente nombras primero?", "final_line": "¿Cuál es la promesa principal?", "cta": "¿Cómo se contacta o compra?"}'::jsonb),
  ('promocional', 'Inscripciones / admisiones', 'Inscripciones', 'post', 'Impulsar inscripciones o solicitudes dentro del periodo vigente.', 'Familias o personas en proceso de decisión.', 'La persona sabe que es momento de inscribirse y qué pasos seguir.', 'Formato: post o reel con fechas, requisitos y enlace/contacto. Datos verificados con la fuente oficial.', '{"hook": "¿Qué urgencia o beneficio real destacas?", "on_screen": "¿Fechas y requisitos clave?", "cta": "¿Enlace, WhatsApp o visita?"}'::jsonb),
  ('promocional', 'Caso de éxito', 'Caso de éxito', 'carousel', 'Demostrar resultados reales para generar confianza en la compra o decisión.', 'Clientes potenciales que se parecen al caso.', 'La persona ve un antes y después creíble y se imagina obteniendo lo mismo.', 'Formato: carrusel reto → solución → resultado. Resultados con evidencia (claim) y autorización del cliente.', '{"hook": "¿Cuál es el resultado más llamativo?", "caption": "¿Qué contexto del cliente incluyes?", "cta": "¿Cómo pide el mismo resultado?"}'::jsonb),
  ('promocional', 'Llamado directo a contacto', 'Llamado a la acción', 'story', 'Convertir interés en contacto directo.', 'Personas que ya conocen la marca y están cerca de decidir.', 'La persona recibe una invitación clara y sencilla para dar el siguiente paso.', 'Formato: story o post con un solo mensaje y un solo botón/enlace.', '{"hook": "¿Qué frase invita a actuar hoy?", "cta": "¿Cuál es el único paso que debe dar?"}'::jsonb);
